  @override
  String adminLdapAttributeTestFailed(Object error, String showError) {
    String _temp0 = intl.Intl.selectLogic(showError, {
      'true': ': $error',
      'other': '',
    });
    return 'Attribute test failed$_temp0';
  }

  @override
  String adminLdapAttributeTestSuccess(num countReturned, num totalCount) {
    String _temp0 = intl.Intl.pluralLogic(
      countReturned,
      locale: localeName,
      other: 'results',
      one: 'result',
    );
    String _temp1 = intl.Intl.pluralLogic(
      totalCount,
      locale: localeName,
      other: 'users',
      one: 'user',
    );
    return 'Attribute test successful: $countReturned $_temp0 found out of $totalCount $_temp1 returned by the user filter';
  }

  @override
  String adminLdapAttributeTestWarning(num totalCount) {
    String _temp0 = intl.Intl.pluralLogic(
      totalCount,
      locale: localeName,
      other: 'users',
      one: 'user',
    );
    return 'The attribute was not found in any of the $totalCount $_temp0 returned by the user filter';
  }

